mapper.select:
select
a.cruise_data_id,
a.cruise_result_id,
a.cruise_id,
a.cruise_type,
a.result_desc,
a.result_num,
a.modify_num,
a.picpath,
a.person_check,
a.origpic,
a.state,
a.evaluation_state,
a.identify_state,
a.identify_result,
a.createtime,
a.remark,
a.check_user,
a.check_date
from t_cruise_data_result a
where 1 = 1
 and a.cruise_data_id = #{cruiseDataId, jdbcType=BIGINT}
 and a.cruise_result_id = #{cruiseResultId, jdbcType=VARCHAR}
 and a.cruise_id = #{cruiseId, jdbcType=BIGINT}
 and a.cruise_type = #{cruiseType, jdbcType=INTEGER}
 and a.result_desc = #{resultDesc, jdbcType=VARCHAR}
 and a.result_num = #{resultNum, jdbcType=VARCHAR}
 and a.modify_num = #{modifyNum, jdbcType=VARCHAR}
 and a.picpath = #{picpath, jdbcType=VARCHAR}
 and a.person_check = #{personCheck, jdbcType=VARCHAR}
 and a.origpic = #{origpic, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.evaluation_state = #{evaluationState, jdbcType=INTEGER}
 and a.identify_state = #{identifyState, jdbcType=INTEGER}
 and a.identify_result = #{identifyResult, jdbcType=INTEGER}
 and a.createtime = #{createtime, jdbcType=TIMESTAMP}
 and a.remark = #{remark, jdbcType=VARCHAR}
 and a.check_user = #{checkUser, jdbcType=VARCHAR}
 and a.check_date = #{checkDate, jdbcType=TIMESTAMP}

